import pytest
from langchain_text_splitters import RecursiveCharacterTextSplitter

def test_chunking_preserves_content_and_splits_properly():
    text = (
        "Retrieval-Augmented Generation (RAG) enhances LLMs by retrieving relevant documents from an external knowledge base. "
        "This ensures that answers are grounded in verified factual data rather than hallucinated facts.\n\n"
        "Vector databases like ChromaDB store high-dimensional embeddings generated by Sentence Transformers. "
        "When a user asks a query, cosine similarity is computed between query vectors and document chunk vectors."
    )

    splitter = RecursiveCharacterTextSplitter(
        chunk_size=120,
        chunk_overlap=20,
        separators=["\n\n", "\n", " ", ""]
    )

    chunks = splitter.split_text(text)
    assert len(chunks) > 1

    # Verify that all words appear across chunks
    combined = " ".join(chunks)
    assert "Retrieval-Augmented" in combined
    assert "ChromaDB" in combined
    assert "cosine similarity" in combined

def test_chunk_metadata_structure():
    doc_id = "doc_test_123"
    filename = "rag_overview.pdf"
    page_number = 2
    chunk_index = 0

    chunk_id = f"{doc_id}_p{page_number}_c{chunk_index}"
    meta = {
        "document_id": doc_id,
        "filename": filename,
        "page_number": page_number,
        "chunk_id": chunk_id
    }

    assert meta["document_id"] == "doc_test_123"
    assert meta["page_number"] == 2
    assert meta["chunk_id"] == "doc_test_123_p2_c0"
